command:
$ErrorActionPreference="Stop"
$endpoint="repos/tngkrwlsmd/flyExplorer/actions/permissions/artifact-and-log-retention"
$raw=(& gh api -H "X-GitHub-Api-Version: 2026-03-10" $endpoint | Out-String)
if($LASTEXITCODE -ne 0){throw "failed to read Actions retention setting"}
$setting=$raw | ConvertFrom-Json
$setting | ConvertTo-Json -Compress
if([int]$setting.days -ne 365){throw "Actions retention setting is not 365 days"}
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
Set-Location -LiteralPath $repo
& git fetch origin main work/actions-retention-365-20261005 --no-tags --prune
if($LASTEXITCODE -ne 0){throw "cleanup fetch failed"}
& git diff --quiet refs/remotes/origin/main refs/remotes/origin/work/actions-retention-365-20261005 --
if($LASTEXITCODE -ne 0){throw "refuse cleanup: merged main tree differs from work branch tree"}
& git push origin --delete work/actions-retention-365-20261005
if($LASTEXITCODE -ne 0){throw "failed to delete merged work branch"}
& git fetch origin --prune --no-tags
if($LASTEXITCODE -ne 0){throw "post-delete fetch failed"}
if(& git show-ref --verify --quiet "refs/remotes/origin/work/actions-retention-365-20261005"){throw "work branch still exists"}
Write-Host "ACTIONS_RETENTION_365_FINAL=PASS"
